  // top-level statements are rejected with a parse error.
  astStatementList scriptStmtTarget = null;

  // Closure definitions (::name(args) { ... }) reduce inside
  // function bodies, long before the enclosing classSection does,
  // so they cannot be attached to their class from the expClosure
  // action. They accumulate here and are drained into the class
  // by the classSection actions. Leftovers at end of parse are
  // top-level script-mode closures; Engine.parseStatements drains
  // those into the synthetic script class.
  List<astFunctDef> pendingClosures = new ArrayList<astFunctDef>();

  public List<astFunctDef> drainPendingClosures() {
      List<astFunctDef> out = this.pendingClosures;
      this.pendingClosures = new ArrayList<astFunctDef>();
      return out;
  }

  public parser(Lexer lex, Engine Eng, String FileName, boolean LoadExternClasses) {
      this(lex, Eng, FileName, LoadExternClasses, null);
  }

  public parser(Lexer lex, Engine Eng, String FileName, boolean LoadExternClasses, astStatementList ScriptStmtTarget) {
      super(lex);
      lexer = lex;
      this.eng = Eng;
      this.fileName = FileName;
      this.loadExternClasses = LoadExternClasses;
      this.scriptStmtTarget = ScriptStmtTarget;
  }

  /**
   * Semantic-action helper for top-level instructions. If a
   * script-statement target is set, append the parsed node to
   * it. Otherwise raise a parse error pointing at the offending
   * statement.
   *
   * report_error filters out non-Symbol info objects, so we set
   * the engine's parse-error flag directly and emit the message
   * via the console (mirroring what report_error does for
   * Symbol-tagged errors).
   */
  private void scriptOrError(astNode n) {
      if (this.scriptStmtTarget == null) {
          this.syntaxErrors = true;
          this.eng.setParseError();
          String msg = "PARSE_ERROR: Top-level statements are not allowed in this "
              + "parse context. Use Engine.setScriptMode(true) and "
              + "Engine.evalLine for script-mode evaluation.";
          aussomException ce = new aussomException(n, msg, "");
          console.get().err(ce.getMessage());
          this.eng.addParseDiagnostic(new ParseDiagnostic(this.fileName,
              n.getLineNum(), n.getColNum(), msg));
          return;
      }
      this.scriptStmtTarget.addNode(n);
  }

  public void report_error(String message, Object info)
  {
    syntaxErrors = true;
    
    if ( !(info instanceof Symbol) ) return;
    Symbol symbol = (Symbol) info;
    
    if ( symbol.left < 0 || symbol.right < 0 ) return;
	
	astNode n = new astNode();
	n.setParserInfo(this.fileName, symbol.left, symbol.right);
	String msg = "PARSE_ERROR: Unknown symbol found at line " + symbol.left + " column " + symbol.right + ".";
	aussomException ce = new aussomException(n, msg, "");
	console.get().err(ce.getMessage());
	this.eng.addParseDiagnostic(new ParseDiagnostic(this.fileName, symbol.left, symbol.right, msg));
	this.eng.setParseError();
	this.done_parsing();					// Forces parser to quit
  }
  
  public void report_fatal_error(String message, Object info)
  {
    this.report_error(message, info);
    this.eng.setParseError();
    this.done_parsing();					// Forces parser to quit
  }
  
  public Engine getEngine() {
  	return this.eng;
  }
  


